import { apiError, apiOk, parseJson, serverError } from '@/lib/api';
import { guard } from '@/lib/guard';
import { schemasFor, uuidSchema } from '@/lib/validation/schemas';
import {
  deleteTrip,
  getOwnedTrip,
  listStops,
  patchTrip,
} from '@/lib/trips/repository';

/**
 * `params` is a Promise in Next 16 — synchronous access was removed. The
 * `RouteContext` helper is generated by `next typegen` and globally available.
 */
export async function GET(request: Request, ctx: RouteContext<'/api/trips/[id]'>) {
  const { id } = await ctx.params;
  if (!uuidSchema.safeParse(id).success) return apiError('NOT_FOUND', 'Unknown trip');

  const guarded = await guard(request, 'writes');
  if (!guarded.ok) return guarded.response;

  try {
    const trip = await getOwnedTrip(guarded.db, id, guarded.context);
    if (!trip) return apiError('NOT_FOUND', 'Unknown trip');

    const tripStops = await listStops(guarded.db, id);
    return apiOk({
      trip,
      stops: tripStops,
      claimed: guarded.context.userId !== null,
      limits: {
        maxStops: guarded.context.limits.maxStops,
        hardMaxStops: guarded.context.limits.hardMaxStops,
      },
    });
  } catch (error) {
    return serverError('GET /api/trips/[id]', error);
  }
}

export async function PATCH(request: Request, ctx: RouteContext<'/api/trips/[id]'>) {
  const { id } = await ctx.params;
  if (!uuidSchema.safeParse(id).success) return apiError('NOT_FOUND', 'Unknown trip');

  const guarded = await guard(request, 'writes');
  if (!guarded.ok) return guarded.response;

  const schemas = schemasFor(guarded.context.tier);
  const parsed = await parseJson(request, schemas.patchTrip);
  if (!parsed.ok) return parsed.response;

  try {
    const result = await patchTrip(guarded.db, id, guarded.context, parsed.data);

    if (result.status === 'not_found') return apiError('NOT_FOUND', 'Unknown trip');
    if (result.status === 'conflict') {
      return apiError('CONFLICT', 'This trip changed in another tab', {
        currentVersion: result.currentVersion,
      });
    }
    return apiOk({ trip: result.trip });
  } catch (error) {
    return serverError('PATCH /api/trips/[id]', error);
  }
}

export async function DELETE(request: Request, ctx: RouteContext<'/api/trips/[id]'>) {
  const { id } = await ctx.params;
  if (!uuidSchema.safeParse(id).success) return apiError('NOT_FOUND', 'Unknown trip');

  const guarded = await guard(request, 'writes');
  if (!guarded.ok) return guarded.response;

  try {
    const removed = await deleteTrip(guarded.db, id, guarded.context);
    if (!removed) return apiError('NOT_FOUND', 'Unknown trip');
    return apiOk({ deleted: true });
  } catch (error) {
    return serverError('DELETE /api/trips/[id]', error);
  }
}
